sys_ux_data_broker_transform.script:
function transform() {
    // System property name containing the JSON array of properties
    var additionalProperties = 'sam.properties';

    // Object to hold the result
    var kpiValues = {
        'properties': []
    };

    // Function to fetch the JSON properties from sam.properties
    function fetchProperties(propertyName) {
        try {
            var propertiesString = gs.getProperty(propertyName); // Get the JSON string
            if (propertiesString) {
                return JSON.parse(propertiesString); // Parse JSON into an array
            }
        } catch (e) {
            gs.log("Error parsing properties from " + propertyName + ": " + e.message);
        }
        return []; // Return empty array in case of error
    }

    // Function to fetch current value for a system property
    function getPropertyValue(propertyName) {
        try {
            return gs.getProperty(propertyName) || "Not Set"; // Fetch the property value or return "Not Set"
        } catch (e) {
            gs.log("Error fetching property value for " + propertyName + ": " + e.message);
            return "Error"; // Return "Error" in case of an exception
        }
    }

    // Fetch the list of properties from the sam.properties JSON
    var propertyList = fetchProperties(additionalProperties);

    // Process each property, fetch its current value, and include the suggested value
    propertyList.forEach(function (item) {
        if (item.property) {
            var currentValue = getPropertyValue(item.property.trim());
            var suggestedValue = item.suggested_value || ""; // Use the suggested value from input, or empty string if not provided
            kpiValues.properties.push({
                'property': item.property.trim(),
                'current_value': currentValue,
                'suggested_value': suggestedValue,
				'name':item.name
            });
        }
    });

    // Return the final values object
    return kpiValues;
}
